formulas.expression:
IF(
AND(
NOT(ISBLANK({!ACH_To_Date})),
{!ACH_Status}={!Off}
),
"ACH Status: " + {!formulaACHStatusStopStart} + " - " + TEXT(MONTH({!ACH_From_Date}))+"/"+TEXT(DAY({!ACH_From_Date}))+"/"+TEXT(YEAR({!ACH_From_Date}))  + "; Resume ACH - " + TEXT(MONTH({!ACH_To_Date}))+"/"+TEXT(DAY({!ACH_To_Date}))+"/"+TEXT(YEAR({!ACH_To_Date}))  + {!formulaLineBreak},
IF(
ISBLANK({!ACH_To_Date}),
"ACH Status: " + {!formulaACHStatusStopStart} + " - " + TEXT(MONTH({!ACH_From_Date}))+"/"+TEXT(DAY({!ACH_From_Date}))+"/"+TEXT(YEAR({!ACH_From_Date})) + {!formulaLineBreak},
IF(
AND(
NOT(ISBLANK({!ACH_To_Date})),
{!ACH_Status}={!On}
),
"ACH Status: " + {!formulaACHStatusStopStart} + " - " + TEXT(MONTH({!ACH_From_Date}))+"/"+TEXT(DAY({!ACH_From_Date}))+"/"+TEXT(YEAR({!ACH_From_Date}))  + ",  to end " + TEXT(MONTH({!ACH_To_Date}))+"/"+TEXT(DAY({!ACH_To_Date}))+"/"+TEXT(YEAR({!ACH_To_Date})) + {!formulaLineBreak},
"ACH Status: " + {!formulaACHStatusStopStart} + " starting on " + TEXT(MONTH({!ACH_From_Date}))+"/"+TEXT(DAY({!ACH_From_Date}))+"/"+TEXT(YEAR({!ACH_From_Date})) 
 + ",  to resume " + TEXT(MONTH({!ACH_To_Date}))+"/"+TEXT(DAY({!ACH_To_Date}))+"/"+TEXT(YEAR({!ACH_To_Date}))  + {!formulaLineBreak}
)))
+ IF({!Stop_Catch_Up_Only}, "Stop Catch Up Only" + BR(), "")

IF(
AND(
NOT(ISBLANK({!Rerun_Action})),
{!Rerun_Action}<> {!DoNotRerun}
),
"Rerun Action: " + {!Rerun_Action} + " on " + TEXT(MONTH({!formulaRerunDate}))+"/"+TEXT(DAY({!formulaRerunDate}))+"/"+TEXT(YEAR({!formulaRerunDate})) + {!formulaLineBreak},
IF(
AND(
NOT(ISBLANK({!Rerun_Action})),
{!Rerun_Action} = {!DoNotRerun}
),
"Rerun Action: " + {!Rerun_Action} + {!formulaLineBreak},
null
))

IF(
AND(
{!Select_Action_Picklist} = {!ModifySchedule}, 
NOT(ISBLANK({!Resume_Existing_Schedule}))
),
{!Select_Action_Picklist} + ": " + TEXT({!No_of_Payments}) + " " + {!Frequency} + " payments of $" + TEXT({!Amount}) + " starting " + TEXT(MONTH({!Start_Date}))+"/"+TEXT(DAY({!Start_Date}))+"/"+TEXT(YEAR({!Start_Date})) + " for a total of $" + TEXT({!formulaTotalAmountModified}) + ". Resume Existing Schedule on " + TEXT(MONTH({!Resume_Existing_Schedule}))+"/"+TEXT(DAY({!Resume_Existing_Schedule}))+"/"+TEXT(YEAR({!Resume_Existing_Schedule})) + {!formulaLineBreak},
{!Select_Action_Picklist} + ": " + TEXT({!No_of_Payments}) + " " + {!Frequency} + " payments of $" + TEXT({!Amount}) + " starting " + TEXT(MONTH({!Start_Date}))+"/"+TEXT(DAY({!Start_Date}))+"/"+TEXT(YEAR({!Start_Date})) + " for a total of $" + TEXT({!formulaTotalAmountModified}) + {!formulaLineBreak}
)
